style.css:
@-moz-document url-prefix("https://google.com") {
body, #docs-editor, .kix-appview-editor {
        background-image: url(https://i.pinimg.com/736x/55/d5/cd/55d5cd291448fadee6a86cd4632d7cd4.jpg) !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
    }

    #docs-chrome *,
    .docs-title-input,
    .goog-menuitem-content {
        font-family: 'Sniglet', 'Chalkboard SE', sans-serif !important;
    }
}
